import os
import sys
import base64
import zipfile
from io import BytesIO
from pathlib import Path

# Base64-encoded ZIP payload (mini_quic_engine_core.zip)
# Generated: mini_quic
# Size: 119,511 bytes (compressed)
ARCHIVE_PAYLOAD = """

"""

def extract_archive(output_dir: str = "mini_quic_engine_core"):
    """Extract the embedded archive to the specified directory."""
    
    # Create output directory
    os.makedirs(output_dir, exist_ok=True)
    
    # Decode base64
    archive_bytes = base64.b64decode(ARCHIVE_PAYLOAD.strip())
    
    # Extract ZIP
    with zipfile.ZipFile(BytesIO(archive_bytes), 'r') as zf:
        zf.extractall(output_dir)
    
    return output_dir

